        protected override void RemoveExplicitlyDefinedChild(BaseInstanceState child)
        {
            if (Object.ReferenceEquals(m_actualControlMode, child))
            {
                m_actualControlMode = null;
                return;
            }

            if (Object.ReferenceEquals(m_actualOperationMode, child))
