        #region Overridden Methods
        public override void GetChildren(
            ISystemContext context,
            IList<BaseInstanceState> children)
        {
            if (m_availability != null)
            {
                children.Add(m_availability);
            }

            if (m_durability != null)
            {
                children.Add(m_durability);
            }

            if (m_expectedReliability != null)
            {
                children.Add(m_expectedReliability);
            }

            if (m_instantaneousAvailability != null)
            {
                children.Add(m_instantaneousAvailability);
            }

            if (m_intrinsicMaintainability != null)
            {
                children.Add(m_intrinsicMaintainability);
            }

            if (m_intrinsicReliability != null)
            {
                children.Add(m_intrinsicReliability);
            }

            if (m_maintainability != null)
            {
