        #region Overridden Methods
        public override void GetChildren(
            ISystemContext context,
            IList<BaseInstanceState> children)
        {
            if (m_criticalBackingPressure != null)
            {
                children.Add(m_criticalBackingPressure);
            }

            if (m_inletAreaOfThePump != null)
            {
                children.Add(m_inletAreaOfThePump);
            }

            if (m_maximumAllowableInletPressure != null)
            {
                children.Add(m_maximumAllowableInletPressure);
            }

            if (m_maximumTolerableWaterVaporInletPressure != null)
            {
                children.Add(m_maximumTolerableWaterVaporInletPressure);
            }

            if (m_maximumWorkingPressure != null)
            {
                children.Add(m_maximumWorkingPressure);
            }

            if (m_minimumAllowableInletPressure != null)
            {
                children.Add(m_minimumAllowableInletPressure);
            }

            if (m_netPositiveInletPressureRequired != null)
            {
                children.Add(m_netPositiveInletPressureRequired);
            }

            if (m_waterVaporCapacity != null)
            {
                children.Add(m_waterVaporCapacity);
            }

            base.GetChildren(context, children);
        }
            
        protected override void RemoveExplicitlyDefinedChild(BaseInstanceState child)
        {
            if (Object.ReferenceEquals(m_criticalBackingPressure, child))
            {
                m_criticalBackingPressure = null;
                return;
            }

            if (Object.ReferenceEquals(m_inletAreaOfThePump, child))
            {
                m_inletAreaOfThePump = null;
                return;
            }

            if (Object.ReferenceEquals(m_maximumAllowableInletPressure, child))
            {
                m_maximumAllowableInletPressure = null;
                return;
            }

            if (Object.ReferenceEquals(m_maximumTolerableWaterVaporInletPressure, child))
            {
                m_maximumTolerableWaterVaporInletPressure = null;
                return;
            }

            if (Object.ReferenceEquals(m_maximumWorkingPressure, child))
            {
                m_maximumWorkingPressure = null;
                return;
            }

            if (Object.ReferenceEquals(m_minimumAllowableInletPressure, child))
            {
                m_minimumAllowableInletPressure = null;
                return;
            }

            if (Object.ReferenceEquals(m_netPositiveInletPressureRequired, child))
            {
                m_netPositiveInletPressureRequired = null;
                return;
            }

            if (Object.ReferenceEquals(m_waterVaporCapacity, child))
            {
                m_waterVaporCapacity = null;
                return;
            }

            base.RemoveExplicitlyDefinedChild(child);
        }

        protected override BaseInstanceState FindChild(
            ISystemContext context,
            QualifiedName browseName,
            bool createOrReplace,
            BaseInstanceState replacement)
        {
            if (QualifiedName.IsNull(browseName))
            {
                return null;
            }

            BaseInstanceState instance = null;

            switch (browseName.Name)
            {
                case Opc.Ua.Pumps.BrowseNames.CriticalBackingPressure:
                {
                    if (createOrReplace)
                    {
                        if (CriticalBackingPressure == null)
                        {
                            if (replacement == null)
                            {
                                CriticalBackingPressure = new BaseAnalogState<double>(this);
                            }
                            else
                            {
                                CriticalBackingPressure = (BaseAnalogState<double>)replacement;
                            }
                        }
                    }

                    instance = CriticalBackingPressure;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.InletAreaOfThePump:
                {
                    if (createOrReplace)
                    {
                        if (InletAreaOfThePump == null)
                        {
                            if (replacement == null)
                            {
                                InletAreaOfThePump = new BaseAnalogState<double>(this);
                            }
                            else
                            {
                                InletAreaOfThePump = (BaseAnalogState<double>)replacement;
                            }
                        }
                    }

                    instance = InletAreaOfThePump;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.MaximumAllowableInletPressure:
                {
                    if (createOrReplace)
                    {
                        if (MaximumAllowableInletPressure == null)
                        {
                            if (replacement == null)
                            {
                                MaximumAllowableInletPressure = new BaseAnalogState<double>(this);
                            }
                            else
                            {
                                MaximumAllowableInletPressure = (BaseAnalogState<double>)replacement;
                            }
                        }
                    }

                    instance = MaximumAllowableInletPressure;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.MaximumTolerableWaterVaporInletPressure:
                {
                    if (createOrReplace)
                    {
                        if (MaximumTolerableWaterVaporInletPressure == null)
                        {
                            if (replacement == null)
                            {
                                MaximumTolerableWaterVaporInletPressure = new BaseAnalogState<double>(this);
                            }
                            else
                            {
                                MaximumTolerableWaterVaporInletPressure = (BaseAnalogState<double>)replacement;
                            }
                        }
                    }

                    instance = MaximumTolerableWaterVaporInletPressure;
