            if (WarmUpTimeForAVaporJetPumpOrADiffusionPump != null)
            {
                WarmUpTimeForAVaporJetPumpOrADiffusionPump.Initialize(context, WarmUpTimeForAVaporJetPumpOrADiffusionPump_InitializationString);
            }

            if (WaterVaporTolerableLoad != null)
            {
                WaterVaporTolerableLoad.Initialize(context, WaterVaporTolerableLoad_InitializationString);
            }

            if (WetCriticalSpeed != null)
            {
                WetCriticalSpeed.Initialize(context, WetCriticalSpeed_InitializationString);
            }
        }

