        #region Overridden Methods
        public override void GetChildren(
            ISystemContext context,
            IList<BaseInstanceState> children)
        {
            if (m_additionalFieldbuses != null)
            {
                children.Add(m_additionalFieldbuses);
            }

            if (m_balancingRateOfFlow != null)
            {
                children.Add(m_balancingRateOfFlow);
            }

            if (m_basePressure != null)
            {
                children.Add(m_basePressure);
            }

            if (m_clearanceVolume != null)
            {
                children.Add(m_clearanceVolume);
            }

            if (m_clockwiseRotation != null)
            {
                children.Add(m_clockwiseRotation);
            }

            if (m_controllable != null)
            {
                children.Add(m_controllable);
            }

            if (m_cool_DownTimeForAVaporJetPumpOrADiffusionPump != null)
            {
                children.Add(m_cool_DownTimeForAVaporJetPumpOrADiffusionPump);
            }

            if (m_counter_ClockwiseRotation != null)
            {
                children.Add(m_counter_ClockwiseRotation);
            }

            if (m_criticalSpeed != null)
            {
                children.Add(m_criticalSpeed);
            }

            if (m_declarationOfConformity != null)
            {
                children.Add(m_declarationOfConformity);
            }

            if (m_declarationOfConformityAvailable != null)
            {
                children.Add(m_declarationOfConformityAvailable);
            }

            if (m_designAxialLoad != null)
            {
                children.Add(m_designAxialLoad);
            }

            if (m_designRadialLoad != null)
            {
                children.Add(m_designRadialLoad);
            }

            if (m_directivesOfEUDeclarationOfConformity != null)
            {
                children.Add(m_directivesOfEUDeclarationOfConformity);
            }

            if (m_dryCriticalSpeed != null)
            {
                children.Add(m_dryCriticalSpeed);
            }

            if (m_explosionProtection != null)
            {
                children.Add(m_explosionProtection);
            }

            if (m_geometricalFlow != null)
            {
