        protected override void RemoveExplicitlyDefinedChild(BaseInstanceState child)
        {
            if (Object.ReferenceEquals(m_current, child))
            {
                m_current = null;
                return;
            }

            if (Object.ReferenceEquals(m_dCLinkCurrent, child))
