        protected override BaseInstanceState FindChild(
            ISystemContext context,
            QualifiedName browseName,
            bool createOrReplace,
            BaseInstanceState replacement)
        {
            if (QualifiedName.IsNull(browseName))
            {
                return null;
            }

            BaseInstanceState instance = null;

            switch (browseName.Name)
            {
                case Opc.Ua.Pumps.BrowseNames.Current:
                {
                    if (createOrReplace)
                    {
                        if (Current == null)
                        {
                            if (replacement == null)
                            {
                                Current = new BaseAnalogState<double>(this);
                            }
                            else
                            {
                                Current = (BaseAnalogState<double>)replacement;
                            }
                        }
                    }

                    instance = Current;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.DCLinkCurrent:
                {
