            BaseInstanceState instance = null;

            switch (browseName.Name)
            {
                case Opc.Ua.Pumps.BrowseNames.AmbientHumidity:
                {
                    if (createOrReplace)
                    {
                        if (AmbientHumidity == null)
                        {
                            if (replacement == null)
                            {
