        protected override void Initialize(ISystemContext context, NodeState source)
        {
            InitializeOptionalChildren(context);
            base.Initialize(context, source);
        }

        protected override void InitializeOptionalChildren(ISystemContext context)
        {
            base.InitializeOptionalChildren(context);

            if (DistributionPriority != null)
            {
                DistributionPriority.Initialize(context, DistributionPriority_InitializationString);
            }

            if (DistributionType != null)
            {
                DistributionType.Initialize(context, DistributionType_InitializationString);
            }

            if (ExchangeMode != null)
            {
                ExchangeMode.Initialize(context, ExchangeMode_InitializationString);
            }

            if (ExchangeTime != null)
            {
                ExchangeTime.Initialize(context, ExchangeTime_InitializationString);
            }

            if (ExchangeTimeDifference != null)
            {
                ExchangeTimeDifference.Initialize(context, ExchangeTimeDifference_InitializationString);
            }

            if (MaximumNumberOfPumpsInOperation != null)
            {
                MaximumNumberOfPumpsInOperation.Initialize(context, MaximumNumberOfPumpsInOperation_InitializationString);
            }

            if (MultiPumpOperationMode != null)
            {
                MultiPumpOperationMode.Initialize(context, MultiPumpOperationMode_InitializationString);
            }

            if (NumberOfPumps != null)
            {
                NumberOfPumps.Initialize(context, NumberOfPumps_InitializationString);
            }

            if (PumpCollectiveIDs != null)
            {
                PumpCollectiveIDs.Initialize(context, PumpCollectiveIDs_InitializationString);
            }

            if (PumpRole != null)
            {
                PumpRole.Initialize(context, PumpRole_InitializationString);
            }

            if (RedundantPumpIDs != null)
            {
                RedundantPumpIDs.Initialize(context, RedundantPumpIDs_InitializationString);
            }
        }

