        protected override BaseInstanceState FindChild(
            ISystemContext context,
            QualifiedName browseName,
            bool createOrReplace,
            BaseInstanceState replacement)
        {
            if (QualifiedName.IsNull(browseName))
            {
                return null;
            }

            BaseInstanceState instance = null;

            switch (browseName.Name)
            {
                case Opc.Ua.Pumps.BrowseNames.ArmatureCircuit:
                {
                    if (createOrReplace)
                    {
                        if (ArmatureCircuit == null)
                        {
                            if (replacement == null)
                            {
                                ArmatureCircuit = new TwoStateDiscreteState(this);
                            }
                            else
                            {
                                ArmatureCircuit = (TwoStateDiscreteState)replacement;
                            }
                        }
                    }

                    instance = ArmatureCircuit;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.CurrentInsideDevice:
                {
                    if (createOrReplace)
                    {
                        if (CurrentInsideDevice == null)
                        {
                            if (replacement == null)
                            {
                                CurrentInsideDevice = new TwoStateDiscreteState(this);
                            }
                            else
                            {
                                CurrentInsideDevice = (TwoStateDiscreteState)replacement;
                            }
                        }
                    }

                    instance = CurrentInsideDevice;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.ElectricalFault:
                {
                    if (createOrReplace)
                    {
                        if (ElectricalFault == null)
                        {
                            if (replacement == null)
                            {
                                ElectricalFault = new TwoStateDiscreteState(this);
                            }
                            else
                            {
                                ElectricalFault = (TwoStateDiscreteState)replacement;
                            }
                        }
                    }

                    instance = ElectricalFault;
                    break;
                }

