                    if (createOrReplace)
                    {
                        if (S1XPhase == null)
                        {
                            if (replacement == null)
                            {
                                S1XPhase = new BaseAnalogState<double>(this);
                            }
                            else
                            {
                                S1XPhase = (BaseAnalogState<double>)replacement;
                            }
                        }
                    }

                    instance = S1XPhase;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.S1XRelativeShaftVibrationP_P:
                {
                    if (createOrReplace)
                    {
                        if (S1XRelativeShaftVibrationP_P == null)
                        {
                            if (replacement == null)
                            {
