        #region Public Properties
        public DriveDesignTypeState Design
        {
            get => m_design;

            set
            {
                if (!Object.ReferenceEquals(m_design, value))
                {
                    ChangeMasks |= NodeStateChangeMasks.Children;
                }

                m_design = value;
            }
        }

        public DriveMeasurementsTypeState Measurements
        {
            get => m_measurements;

            set
            {
                if (!Object.ReferenceEquals(m_measurements, value))
                {
                    ChangeMasks |= NodeStateChangeMasks.Children;
                }

                m_measurements = value;
            }
        }
        #endregion

        #region Overridden Methods
        public override void GetChildren(
            ISystemContext context,
            IList<BaseInstanceState> children)
        {
            if (m_design != null)
            {
                children.Add(m_design);
            }

            if (m_measurements != null)
            {
                children.Add(m_measurements);
            }

            base.GetChildren(context, children);
        }
            
        protected override void RemoveExplicitlyDefinedChild(BaseInstanceState child)
        {
            if (Object.ReferenceEquals(m_design, child))
            {
                m_design = null;
                return;
            }

            if (Object.ReferenceEquals(m_measurements, child))
            {
                m_measurements = null;
                return;
            }

            base.RemoveExplicitlyDefinedChild(child);
        }

        protected override BaseInstanceState FindChild(
            ISystemContext context,
            QualifiedName browseName,
            bool createOrReplace,
            BaseInstanceState replacement)
        {
            if (QualifiedName.IsNull(browseName))
            {
                return null;
            }

            BaseInstanceState instance = null;

            switch (browseName.Name)
            {
                case Opc.Ua.Pumps.BrowseNames.Design:
                {
                    if (createOrReplace)
                    {
                        if (Design == null)
                        {
                            if (replacement == null)
                            {
                                Design = new DriveDesignTypeState(this);
                            }
                            else
                            {
                                Design = (DriveDesignTypeState)replacement;
                            }
                        }
                    }

                    instance = Design;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.Measurements:
                {
                    if (createOrReplace)
                    {
                        if (Measurements == null)
                        {
                            if (replacement == null)
                            {
                                Measurements = new DriveMeasurementsTypeState(this);
                            }
                            else
                            {
                                Measurements = (DriveMeasurementsTypeState)replacement;
                            }
                        }
                    }

                    instance = Measurements;
                    break;
                }
            }

            if (instance != null)
            {
                return instance;
            }

            return base.FindChild(context, browseName, createOrReplace, replacement);
        }
        #endregion

        #region Private Fields
        private DriveDesignTypeState m_design;
        private DriveMeasurementsTypeState m_measurements;
        #endregion
    }
