        protected override void RemoveExplicitlyDefinedChild(BaseInstanceState child)
        {
            if (Object.ReferenceEquals(m_design, child))
            {
                m_design = null;
                return;
            }

            if (Object.ReferenceEquals(m_implementation, child))
            {
                m_implementation = null;
                return;
            }

            if (Object.ReferenceEquals(m_measurements, child))
            {
                m_measurements = null;
                return;
            }

            if (Object.ReferenceEquals(m_systemRequirements, child))
            {
                m_systemRequirements = null;
                return;
            }

            base.RemoveExplicitlyDefinedChild(child);
        }

        protected override BaseInstanceState FindChild(
            ISystemContext context,
            QualifiedName browseName,
            bool createOrReplace,
            BaseInstanceState replacement)
        {
            if (QualifiedName.IsNull(browseName))
            {
                return null;
            }

            BaseInstanceState instance = null;

            switch (browseName.Name)
            {
                case Opc.Ua.Pumps.BrowseNames.Design:
                {
                    if (createOrReplace)
                    {
                        if (Design == null)
                        {
                            if (replacement == null)
                            {
                                Design = new InletConnectionDesignTypeState(this);
                            }
                            else
                            {
                                Design = (InletConnectionDesignTypeState)replacement;
                            }
                        }
                    }

                    instance = Design;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.Implementation:
                {
                    if (createOrReplace)
                    {
                        if (Implementation == null)
                        {
                            if (replacement == null)
                            {
                                Implementation = new InletConnectionImplementationTypeState(this);
                            }
                            else
                            {
                                Implementation = (InletConnectionImplementationTypeState)replacement;
                            }
                        }
                    }

                    instance = Implementation;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.Measurements:
                {
                    if (createOrReplace)
                    {
                        if (Measurements == null)
                        {
                            if (replacement == null)
                            {
                                Measurements = new InletConnectionMeasurementsTypeState(this);
                            }
                            else
                            {
                                Measurements = (InletConnectionMeasurementsTypeState)replacement;
                            }
                        }
                    }

                    instance = Measurements;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.SystemRequirements:
                {
                    if (createOrReplace)
                    {
                        if (SystemRequirements == null)
                        {
                            if (replacement == null)
                            {
                                SystemRequirements = new InletConnectionSystemRequirementsTypeState(this);
                            }
                            else
                            {
                                SystemRequirements = (InletConnectionSystemRequirementsTypeState)replacement;
                            }
                        }
                    }

                    instance = SystemRequirements;
                    break;
                }
            }

            if (instance != null)
            {
                return instance;
            }

            return base.FindChild(context, browseName, createOrReplace, replacement);
        }
