        #region Public Properties
        public OutletConnectionDesignTypeState Design
        {
            get => m_design;

            set
            {
                if (!Object.ReferenceEquals(m_design, value))
                {
                    ChangeMasks |= NodeStateChangeMasks.Children;
                }

                m_design = value;
            }
        }

        public OutletConnectionImplementationTypeState Implementation
        {
            get => m_implementation;

            set
            {
                if (!Object.ReferenceEquals(m_implementation, value))
                {
                    ChangeMasks |= NodeStateChangeMasks.Children;
                }

                m_implementation = value;
            }
        }

        public OutletConnectionMeasurementsTypeState Measurements
        {
            get => m_measurements;

            set
            {
                if (!Object.ReferenceEquals(m_measurements, value))
                {
                    ChangeMasks |= NodeStateChangeMasks.Children;
                }

                m_measurements = value;
            }
        }

        public OutletConnectionSystemRequirementsTypeState SystemRequirements
        {
            get => m_systemRequirements;

            set
            {
                if (!Object.ReferenceEquals(m_systemRequirements, value))
                {
                    ChangeMasks |= NodeStateChangeMasks.Children;
                }

                m_systemRequirements = value;
            }
        }
        #endregion

        #region Overridden Methods
        public override void GetChildren(
            ISystemContext context,
            IList<BaseInstanceState> children)
        {
            if (m_design != null)
            {
                children.Add(m_design);
            }

            if (m_implementation != null)
            {
                children.Add(m_implementation);
            }

            if (m_measurements != null)
            {
                children.Add(m_measurements);
            }

            if (m_systemRequirements != null)
            {
                children.Add(m_systemRequirements);
            }

            base.GetChildren(context, children);
        }
            
        protected override void RemoveExplicitlyDefinedChild(BaseInstanceState child)
        {
            if (Object.ReferenceEquals(m_design, child))
            {
                m_design = null;
                return;
            }

            if (Object.ReferenceEquals(m_implementation, child))
            {
                m_implementation = null;
                return;
            }

            if (Object.ReferenceEquals(m_measurements, child))
            {
                m_measurements = null;
                return;
            }

            if (Object.ReferenceEquals(m_systemRequirements, child))
            {
                m_systemRequirements = null;
                return;
            }

            base.RemoveExplicitlyDefinedChild(child);
        }

        protected override BaseInstanceState FindChild(
            ISystemContext context,
            QualifiedName browseName,
            bool createOrReplace,
            BaseInstanceState replacement)
        {
            if (QualifiedName.IsNull(browseName))
            {
                return null;
            }

            BaseInstanceState instance = null;

            switch (browseName.Name)
            {
                case Opc.Ua.Pumps.BrowseNames.Design:
                {
                    if (createOrReplace)
                    {
                        if (Design == null)
                        {
                            if (replacement == null)
                            {
                                Design = new OutletConnectionDesignTypeState(this);
                            }
                            else
                            {
                                Design = (OutletConnectionDesignTypeState)replacement;
                            }
                        }
                    }

                    instance = Design;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.Implementation:
                {
                    if (createOrReplace)
                    {
                        if (Implementation == null)
