        #region Overridden Methods
        public override void GetChildren(
            ISystemContext context,
            IList<BaseInstanceState> children)
        {
            if (m_configuration != null)
            {
                children.Add(m_configuration);
            }

            if (m_documentation != null)
            {
                children.Add(m_documentation);
            }

            if (m_events != null)
            {
                children.Add(m_events);
            }

            if (m_maintenance != null)
            {
                children.Add(m_maintenance);
            }

            if (m_operational != null)
            {
                children.Add(m_operational);
            }

            if (m_ports != null)
            {
                children.Add(m_ports);
            }

            base.GetChildren(context, children);
        }
            
        protected override void RemoveExplicitlyDefinedChild(BaseInstanceState child)
        {
            if (Object.ReferenceEquals(m_configuration, child))
            {
                m_configuration = null;
                return;
            }

            if (Object.ReferenceEquals(m_documentation, child))
            {
                m_documentation = null;
                return;
            }

            if (Object.ReferenceEquals(m_events, child))
            {
                m_events = null;
                return;
            }

            if (Object.ReferenceEquals(m_maintenance, child))
            {
                m_maintenance = null;
                return;
            }

            if (Object.ReferenceEquals(m_operational, child))
            {
                m_operational = null;
                return;
            }

            if (Object.ReferenceEquals(m_ports, child))
            {
                m_ports = null;
                return;
            }

            base.RemoveExplicitlyDefinedChild(child);
        }

        protected override BaseInstanceState FindChild(
            ISystemContext context,
            QualifiedName browseName,
            bool createOrReplace,
            BaseInstanceState replacement)
        {
            if (QualifiedName.IsNull(browseName))
            {
                return null;
            }

            BaseInstanceState instance = null;

            switch (browseName.Name)
            {
                case Opc.Ua.DI.BrowseNames.Configuration:
                {
                    if (createOrReplace)
                    {
                        if (Configuration == null)
                        {
                            if (replacement == null)
                            {
                                Configuration = new ConfigurationGroupTypeState(this);
                            }
                            else
                            {
                                Configuration = (ConfigurationGroupTypeState)replacement;
                            }
                        }
                    }

                    instance = Configuration;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.Documentation:
                {
                    if (createOrReplace)
                    {
                        if (Documentation == null)
                        {
                            if (replacement == null)
                            {
                                Documentation = new DocumentationTypeState(this);
                            }
                            else
                            {
                                Documentation = (DocumentationTypeState)replacement;
                            }
                        }
                    }

                    instance = Documentation;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.Events:
                {
                    if (createOrReplace)
                    {
                        if (Events == null)
                        {
                            if (replacement == null)
                            {
                                Events = new SupervisionTypeState(this);
                            }
                            else
                            {
                                Events = (SupervisionTypeState)replacement;
                            }
                        }
                    }

                    instance = Events;
                    break;
                }

                case Opc.Ua.DI.BrowseNames.Identification:
                {
                    if (createOrReplace)
                    {
                        if (Identification == null)
                        {
                            if (replacement == null)
                            {
                                Identification = new PumpIdentificationTypeState(this);
                            }
                            else
                            {
                                Identification = (PumpIdentificationTypeState)replacement;
                            }
                        }
                    }

                    instance = Identification;
                    break;
                }

                case Opc.Ua.DI.BrowseNames.Maintenance:
                {
                    if (createOrReplace)
                    {
                        if (Maintenance == null)
                        {
                            if (replacement == null)
                            {
                                Maintenance = new MaintenanceGroupTypeState(this);
                            }
                            else
                            {
                                Maintenance = (MaintenanceGroupTypeState)replacement;
                            }
                        }
                    }

                    instance = Maintenance;
                    break;
                }

                case Opc.Ua.DI.BrowseNames.Operational:
                {
                    if (createOrReplace)
                    {
                        if (Operational == null)
                        {
                            if (replacement == null)
                            {
                                Operational = new OperationalGroupTypeState(this);
                            }
                            else
                            {
                                Operational = (OperationalGroupTypeState)replacement;
                            }
                        }
                    }

                    instance = Operational;
                    break;
                }

                case Opc.Ua.Pumps.BrowseNames.Ports:
                {
                    if (createOrReplace)
                    {
                        if (Ports == null)
                        {
                            if (replacement == null)
                            {
                                Ports = new PortsGroupTypeState(this);
                            }
                            else
                            {
                                Ports = (PortsGroupTypeState)replacement;
                            }
                        }
                    }

                    instance = Ports;
                    break;
                }
            }

            if (instance != null)
            {
                return instance;
            }

            return base.FindChild(context, browseName, createOrReplace, replacement);
        }
        #endregion

