        private ConfigurationGroupTypeState m_configuration;
        private DocumentationTypeState m_documentation;
        private SupervisionTypeState m_events;
        private MaintenanceGroupTypeState m_maintenance;
        private OperationalGroupTypeState m_operational;
        private PortsGroupTypeState m_ports;
        #endregion
